// ============================================================
// Titel zerlegen, 00-Seiten ausklammern, Inhaltshash bilden.
// Die H1-Ebene besteht in Confluence aus ORDNERN und kommt nicht
// aus der Seiten-API. Ihre Namen liefert Bereichsordner laden;
// die Zuordnung laeuft ueber das Kuerzel im Ordnertitel.
//
// Ein Bereich ohne passenden Ordner haelt den Lauf NICHT an - er
// wird uebersprungen und in der Zusammenfassung gemeldet. Sonst
// blockiert ein einziger neu angelegter Bereich die Spiegelung
// aller uebrigen.
// ============================================================
const crypto = require('crypto');
const cfg = $('Config').first().json;
const bereichFilter = String(cfg.bereichFilter || '').trim();

const RE_H3 = /^([A-Z]{2,4})-(\d{2})-(\d{2})\s*[–-]\s*(.+)$/;
const RE_H2 = /^([A-Z]{2,4})-(\d{2})\s*[–-]\s*(.+)$/;
const RE_00 = /^00[.\-]/;
const RE_ORDNER = /^([A-Z]{2,4})\s*[–-]\s*(.+)$/;

// --- Bereichsordner der H1-Ebene ---
const bereichsOrdner = {};
const ordnerDoppelt = [];
const ordnerOhneKuerzel = [];
for (const item of $('Bereichsordner laden').all()) {
  const r = item.json || {};
  const liste = Array.isArray(r.results) ? r.results : [r];
  for (const f of liste) {
    if (!f || String(f.type || '') !== 'folder') continue;
    const t = String(f.title || '').trim();
    const m = t.match(RE_ORDNER);
    if (!m) {
      // Ordner, der der Namenskonvention KUERZEL - Klartext nicht folgt.
      // Seine Seiten finden spaeter keinen Zielpfad.
      if (!/^00[\s.-]/.test(t)) ordnerOhneKuerzel.push(t);
      continue;
    }
    if (bereichsOrdner[m[1]]) {
      ordnerDoppelt.push(m[1] + ': ' + bereichsOrdner[m[1]].titel + ' / ' + t);
    }
    bereichsOrdner[m[1]] = { titel: t, klartext: m[2].trim() };
  }
}

if (Object.keys(bereichsOrdner).length === 0) {
  throw new Error('KEINE_BEREICHSORDNER: Die H1-Ebene kam leer an. Ohne Ordnernamen kein Zielpfad.');
}

// --- Seiten einsammeln ---
const rohSeiten = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (Array.isArray(r.results)) {
    for (const p of r.results) rohSeiten.push(p);
  } else if (r.id && r.title) {
    rohSeiten.push(r);
  }
}

if (rohSeiten.length === 0) {
  throw new Error('KEINE_SEITEN: Der Confluence-Abruf hat nichts geliefert. Keine Weiterverarbeitung.');
}

function inhaltVon(p) {
  const b = p.body || {};
  if (b.storage && typeof b.storage.value === 'string') return b.storage.value;
  if (b.atlas_doc_format && typeof b.atlas_doc_format.value === 'string') return b.atlas_doc_format.value;
  if (b.view && typeof b.view.value === 'string') return b.view.value;
  return '';
}

// --- Titel zerlegen ---
const erkannt = [];
const verworfen = [];
const ohneOrdner = [];

for (const p of rohSeiten) {
  const titel = String(p.title || '').trim();
  const pageId = String(p.id || '');
  if (!pageId) continue;

  if (RE_00.test(titel)) {
    verworfen.push({ page_id: pageId, titel, grund: 'Orientierungsseite 00' });
    continue;
  }

  let ebene = null, bereich = null, gruppeNr = null, prozessNr = null, klartext = null;
  let m = titel.match(RE_H3);
  if (m) {
    ebene = 'prozess'; bereich = m[1]; gruppeNr = m[1] + '-' + m[2];
    prozessNr = m[1] + '-' + m[2] + '-' + m[3]; klartext = m[4].trim();
  } else {
    m = titel.match(RE_H2);
    if (m) {
      ebene = 'gruppe'; bereich = m[1]; gruppeNr = m[1] + '-' + m[2];
      prozessNr = ''; klartext = m[3].trim();
    }
  }

  if (!ebene) {
    verworfen.push({ page_id: pageId, titel, grund: 'Titel folgt nicht der Systematik' });
    continue;
  }

  if (bereichFilter && bereich !== bereichFilter) {
    verworfen.push({ page_id: pageId, titel, grund: 'Nicht im gewaehlten Bereich ' + bereichFilter });
    continue;
  }

  const ordner = bereichsOrdner[bereich] || null;

  if (!ordner) {
    // Kein Ordner mit diesem Kuerzel auf der H1-Ebene. Ueberspringen
    // statt abbrechen - der Rest des Bestands soll trotzdem laufen.
    ohneOrdner.push({ bereich, titel });
    continue;
  }

  const inhalt = inhaltVon(p);

  erkannt.push({
    page_id: pageId,
    space_key: cfg.spaceKey,
    titel,
    ebene,
    bereich,
    bereich_ordner: ordner.titel,
    bereich_klartext: ordner.klartext,
    bereich_ordner_fehlt: false,
    gruppe_nr: gruppeNr,
    prozess_nr: prozessNr,
    klartext,
    inhalt,
    inhalt_leer: inhalt.length === 0,
    version: (p.version && p.version.number) || 0,
    geaendert_am: (p.version && (p.version.when || p.version.createdAt)) || '',
    web_url: cfg.confluenceBasis + '/spaces/' + cfg.spaceKey + '/pages/' + pageId,
    content_hash: crypto.createHash('sha256').update(titel + ' ' + inhalt, 'utf8').digest('hex'),
    ordner_doppelt: ordnerDoppelt,
    ordner_ohne_kuerzel: ordnerOhneKuerzel,
    bereiche_ohne_ordner: Array.from(new Set(ohneOrdner.map(x => x.bereich))).sort(),
    seiten_ohne_ordner: ohneOrdner.length
  });
}

// Die Sammelfelder erst am Ende in alle Datensaetze schreiben, damit
// auch Seiten davon wissen, die vor dem letzten Fund verarbeitet wurden.
const bereicheOhne = Array.from(new Set(ohneOrdner.map(x => x.bereich))).sort();
for (const e of erkannt) {
  e.bereiche_ohne_ordner = bereicheOhne;
  e.seiten_ohne_ordner = ohneOrdner.length;
}

// --- Gruppentitel fuer die zweite Ordnerebene ---
const gruppenTitel = {};
for (const e of erkannt) {
  if (e.ebene === 'gruppe') gruppenTitel[e.gruppe_nr] = e.klartext;
}

for (const e of erkannt) {
  e.gruppe_titel = gruppenTitel[e.gruppe_nr] || '';
  e.gruppe_titel_fehlt = !gruppenTitel[e.gruppe_nr];
}

if (erkannt.length === 0) {
  throw new Error(
    'NICHTS_ZU_SPIEGELN: Keine einzige Seite hat einen Zielpfad. ' +
    'Bereiche ohne Ordner: ' + (bereicheOhne.join(', ') || 'keine') + '. ' +
    'Ordner ohne Kuerzel im Namen: ' + (ordnerOhneKuerzel.join(' / ') || 'keine') + '.'
  );
}

const leere = erkannt.filter(e => e.inhalt_leer).length;
if (leere === erkannt.length && erkannt.length > 0) {
  throw new Error(
    'INHALT_LEER: Alle ' + erkannt.length + ' Seiten kamen ohne Text an. ' +
    'Vermutlich liefert body.storage bei diesem Bereich nichts.'
  );
}

return erkannt.map(e => ({ json: e }));

// ============================================================
// Vergleicht den Confluence-Stand mit dem Bestand des letzten Laufs.
// Ergebnis je Seite in "aktion": spiegeln, entfernen oder nichts.
//
// gruppenseitenSpiegeln steuert, ob die H2-Gruppenseiten als eigene
// Datei abgelegt werden. Steht der Schalter auf false, dienen sie nur
// noch als Quelle fuer den Ordnernamen - die Ablage enthaelt dann
// ausschliesslich H3-Prozessseiten.
//
// neuAufbauen erzwingt das Neuschreiben aller Seiten, auch wenn sich
// der Inhalt nicht geaendert hat. Gedacht fuer Aenderungen am Template:
// der content_hash bildet nur die Confluence-Seite ab, nicht die
// Aufbereitung - ohne Schalter bliebe eine Layoutaenderung unsichtbar.
//
// Die Loeschsicherung stammt aus dem RAG-Ingest und hat sich dort
// bewaehrt: Ein Aussetzer der Confluence-API darf die Zielablage
// nicht leerraeumen.
// ============================================================
const cfg = $('Config').first().json;
const maxProzent = Number(cfg.loeschSicherungProzent != null ? cfg.loeschSicherungProzent : 35);
const mindestBestand = Number(cfg.loeschSicherungMindestbestand != null ? cfg.loeschSicherungMindestbestand : 20);
const bereichFilter = String(cfg.bereichFilter || '').trim();
const neuAufbauen = cfg.neuAufbauen === true;
const gruppenSpiegeln = cfg.gruppenseitenSpiegeln === true;

const aktuelle = $('Zielpfade bestimmen').all().map(i => i.json).filter(s => s && s.page_id);

// Bestand einsammeln. Die Data Table liefert je Zeile ein Item.
const bestand = new Map();
for (const item of $input.all()) {
  const r = item.json;
  if (!r || !r.page_id) continue;
  if (bereichFilter && String(r.bereich || '') !== bereichFilter) continue;
  bestand.set(String(r.page_id), r);
}

const aktuelleIds = new Set(aktuelle.map(s => String(s.page_id)));

if (bestand.size > 0 && aktuelleIds.size === 0) {
  throw new Error(
    'LOESCHSCHUTZ_CONFLUENCE_LEER: Der Bestand kennt ' + bestand.size +
    ' Seiten, der aktuelle Abruf aber keine. Es wird nichts entfernt.'
  );
}

// Geloeschte bestimmen
const geloescht = [];
for (const [pid, row] of bestand) {
  if (!aktuelleIds.has(pid)) geloescht.push(row);
}

if (geloescht.length > 0 && bestand.size >= mindestBestand) {
  const anteil = (geloescht.length / bestand.size) * 100;
  if (anteil > maxProzent) {
    throw new Error(
      'LOESCHSCHUTZ_ANTEIL: ' + geloescht.length + ' von ' + bestand.size +
      ' Seiten fehlen (' + anteil.toFixed(1) + ' Prozent, erlaubt sind ' + maxProzent +
      '). Es wird nichts entfernt.'
    );
  }
}

const aus = [];

for (const s of aktuelle) {
  // Gruppenseiten liefern den Ordnernamen und werden nur auf Wunsch abgelegt
  if (s.ebene === 'gruppe' && !gruppenSpiegeln) {
    aus.push({ json: Object.assign({}, s, {
      aktion: 'nichts',
      grund: 'Gruppenseite, dient nur als Ordnername',
      status: 'uebersprungen'
    }) });
    continue;
  }

  const alt = bestand.get(String(s.page_id));
  const gleich = !!alt && String(alt.content_hash || '') === String(s.content_hash || '');

  // Der Ablageort haengt an den Ueberschriften - der eigenen und der der
  // Gruppe. Aendert sich eine davon, wandert die Datei, ohne dass sich der
  // Fingerabdruck der Seite selbst aendert. Ohne diesen Vergleich bliebe
  // die Seite als unveraendert liegen und am neuen Ort entstuende nie eine
  // Datei - die alte bliebe als Waise zurueck.
  const altPfad = alt ? (String(alt.sp_ordner || '') + '/' + String(alt.sp_datei || '')) : '';
  const pfadGleich = !alt || altPfad === String(s.sp_pfad || '');

  const unveraendert = gleich && pfadGleich && !neuAufbauen;

  aus.push({
    json: Object.assign({}, s, {
      aktion: unveraendert ? 'nichts' : 'spiegeln',
      grund: !alt ? 'neu' : (!pfadGleich ? 'umgezogen' : (gleich ? (neuAufbauen ? 'neuaufbau erzwungen' : 'unveraendert') : 'geaendert')),
      sp_item_id: (alt && alt.sp_item_id) || '',
      status: 'offen'
    })
  });
}

for (const row of geloescht) {
  const ordner = String(row.sp_ordner || '');
  const datei = String(row.sp_datei || '');
  aus.push({
    json: {
      aktion: 'entfernen',
      grund: 'in Confluence nicht mehr vorhanden',
      page_id: String(row.page_id),
      space_key: row.space_key,
      titel: row.titel,
      ebene: row.ebene,
      bereich: row.bereich,
      gruppe_nr: row.gruppe_nr,
      prozess_nr: row.prozess_nr,
      sp_ordner: ordner,
      sp_datei: datei,
      sp_pfad: ordner && datei ? ordner + '/' + datei : '',
      sp_item_id: row.sp_item_id || ''
    }
  });
}

return aus;

// ============================================================
// Confluence-Inhalt ins RWG-Template. Erzeugt das fertige HTML
// und den Ablagepfad in SharePoint.
//
// Die Ordnernamen der H1-Ebene kommen aus Confluence und stehen
// im Datensatz. Es gibt keine gepflegte Bereichstabelle mehr.
//
// Farben nach KAPA Digital: Primaerblau 1B4FD8 traegt weissen Text
// (6,65:1) und steht an Kopflinie, Tabellenkoepfen und Prozesskuerzel.
// Dunkelblau 0D2B55 fuer Ueberschriften (14,06:1). Cyan 0891B2 nur an
// Kanten - es traegt mit 3,68:1 keinen Text.
//
// ACHTUNG Entities: Das Storage-Format kodiert Umlaute als &Auml;
// und &auml;. Wer nach dem Zeichen sucht, findet nichts, und wer den
// Text ein zweites Mal escapt, macht aus &auml; ein sichtbares
// &amp;auml;.
//
// Die Datei geht als Binary mit UTF-8-BOM hinaus. SharePoint uebernimmt
// beim Hochladen die Spalte Titel aus <title> und liest den Kopf dabei
// nach Windows-1252, wenn ihm die Kodierung nicht aufgezwungen wird -
// die Umlaute stehen dann in der Bibliotheksansicht zerlegt. Die Bytes
// in der Datei sind auch ohne BOM korrekt, nur der Leser raet falsch.
// Der eigene Buffer schliesst zugleich jede Latin-1-Zwischenstufe im
// HTTP-Node aus.
//
// sp_pfad_url traegt denselben Pfad je Segment prozentkodiert. Ordner-
// und Dateinamen enthalten Leerzeichen und Umlaute; ein Titel mit # oder
// % wuerde eine ungekodierte URL sofort zerreissen.
// ============================================================
const cfg = $('Config').first().json;

function sicherName(s) {
  return String(s || '')
    .replace(/&amp;/g, 'und').replace(/&/g, 'und')
    .replace(/[":*<>?/\\|]/g, '-')
    .replace(/[–—]/g, '-')
    .replace(/\s+/g, ' ')
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 120);
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function bereinige(html) {
  let h = String(html || '');

  // --- ADF-Panels: nur den Inhalt behalten, Fallback und Attribute verwerfen ---
  h = h.replace(/<ac:adf-extension>[\s\S]*?<\/ac:adf-extension>/gi, (block) => {
    const art = (block.match(/<ac:adf-attribute[^>]*key="panel-type"[^>]*>([\s\S]*?)<\/ac:adf-attribute>/i) || [])[1] || 'info';
    const inhalt = (block.match(/<ac:adf-content>([\s\S]*?)<\/ac:adf-content>/i) || [])[1] || '';
    if (!inhalt.trim()) return '';
    const klasse = /warn|error/i.test(art) ? 'warnung' : 'hinweis';
    return '<aside class="' + klasse + '">' + inhalt + '</aside>';
  });

  // --- Klassische Makros ---
  h = h.replace(/<ac:structured-macro[^>]*ac:name="(toc|change-history)"[\s\S]*?(?:\/>|<\/ac:structured-macro>)/gi, '');
  h = h.replace(/<ac:structured-macro[^>]*ac:name="(info|note|tip)"[\s\S]*?<ac:rich-text-body>([\s\S]*?)<\/ac:rich-text-body>[\s\S]*?<\/ac:structured-macro>/gi,
    '<aside class="hinweis">$2</aside>');
  h = h.replace(/<ac:structured-macro[^>]*ac:name="(warning|error|note)"[\s\S]*?<ac:rich-text-body>([\s\S]*?)<\/ac:rich-text-body>[\s\S]*?<\/ac:structured-macro>/gi,
    '<aside class="warnung">$2</aside>');

  // Parameter tragen Werte wie "note" als Text - vor dem Tag-Abraeumen entfernen
  h = h.replace(/<ac:parameter[\s\S]*?<\/ac:parameter>/gi, '');
  h = h.replace(/<ac:adf-attribute[\s\S]*?<\/ac:adf-attribute>/gi, '');
  h = h.replace(/<ac:adf-fallback>[\s\S]*?<\/ac:adf-fallback>/gi, '');

  // Was jetzt noch an Makros steht, hat keinen darstellbaren Inhalt
  h = h.replace(/<ac:structured-macro[\s\S]*?<\/ac:structured-macro>/gi, '');
  h = h.replace(/<ac:[a-z-]+[^>]*\/>/gi, '');
  h = h.replace(/<\/?ac:[a-z-]+[^>]*>/gi, '');
  h = h.replace(/<\/?ri:[a-z-]+[^>]*>/gi, '');

  // --- ADF-Ausgabe der v2-API, falls dieser Weg einmal genutzt wird ---
  h = h.replace(/<div[^>]*data-type="extension"[^>]*>\s*<\/div>/gi, '');
  h = h.replace(/<div[^>]*data-type="panel-info"[^>]*>([\s\S]*?)<\/div>/gi, '<aside class="hinweis">$1</aside>');
  h = h.replace(/<div[^>]*data-type="panel-(warning|error)"[^>]*>([\s\S]*?)<\/div>/gi, '<aside class="warnung">$2</aside>');

  // --- Die beiden Makro-Ueberschriften am Seitenanfang ---
  h = h.replace(/<h1[^>]*>\s*Inhaltsverzeichnis\s*<\/h1>/gi, '');
  // Umlaute stehen im Storage-Format als Entities: &Auml;nderungshistorie
  h = h.replace(/<h1[^>]*>\s*(&Auml;|&auml;|Ä|A)e?nderungshistorie\s*<\/h1>/gi, '');

  // --- Tabellen: Confluence liefert die Kopfzeile als <tr><th> ohne <thead> ---
  h = h.replace(/<table[^>]*>/gi, '<table>');
  h = h.replace(/\sdata-layout="[^"]*"/gi, '');

  // Fremde Inline-Styles aus Fallback-Bloecken haben hier nichts verloren
  h = h.replace(/\sstyle="[^"]*"/gi, '');

  return h.trim();
}

function verzeichnis(html) {
  const eintraege = [];
  const re = /<h2[^>]*>([\s\S]*?)<\/h2>/gi;
  let m, i = 0;
  while ((m = re.exec(html)) !== null) {
    // Text bleibt HTML-kodiert - er wird unveraendert ins Verzeichnis uebernommen.
    // Ein zusaetzliches Escapen wuerde aus &auml; ein sichtbares &amp;auml; machen.
    const text = m[1].replace(/<[^>]+>/g, '').trim();
    if (text) eintraege.push({ id: 'abschnitt-' + (++i), text });
  }
  return eintraege;
}

function ankerSetzen(html, eintraege) {
  let i = 0;
  return html.replace(/<h2[^>]*>/gi, () => {
    const e = eintraege[i++];
    return e ? '<h2 id="' + e.id + '">' : '<h2>';
  });
}

function relativerPfad(vonOrdner, nachOrdner, datei) {
  let i = 0;
  while (i < vonOrdner.length && i < nachOrdner.length && vonOrdner[i] === nachOrdner[i]) i++;
  const auf = vonOrdner.slice(i).map(() => '..');
  const ab = nachOrdner.slice(i);
  return auf.concat(ab, [datei]).map(encodeURIComponent).join('/').replace(/%2F/g, '/');
}

function linksUmschreiben(html, karte, eigenerOrdner) {
  return String(html).replace(
    /<a\s+[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi,
    (treffer, url, text) => {
      const m = String(url).match(/\/pages\/(\d+)/);
      const ziel = m ? karte[m[1]] : null;
      if (ziel) {
        return '<a href="' + relativerPfad(eigenerOrdner, ziel.ordner, ziel.datei) + '">' + text + '</a>';
      }
      if (/atlassian\.net/.test(url)) {
        return '<span class="link-tot" title="Verweis auf eine nicht gespiegelte Seite">' + text + '</span>';
      }
      return treffer;
    }
  );
}

const STIL = ':root{--akzent:#0891B2;--marke:#1B4FD8;--marke-hell:#E8EEFC;--marke-tief:#0D2B55;--tinte:#14203A;--tinte-weich:#47506B;--tinte-blass:#7A8299;--linie:#DEE3EC;--linie-kraeftig:#BAC2D2;--papier:#FFFFFF;--papier-ton:#F6F7FA}'
  + '*{box-sizing:border-box}'
  + 'body{margin:0;background:var(--papier-ton);color:var(--tinte);font-family:"Segoe UI",-apple-system,BlinkMacSystemFont,Roboto,Arial,sans-serif;font-size:15px;line-height:1.6;-webkit-font-smoothing:antialiased}'
  + '.blatt{max-width:1040px;margin:0 auto;background:var(--papier);min-height:100vh;padding:0 0 56px;box-shadow:0 0 0 1px var(--linie)}'
  + '.kopf{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;flex-wrap:wrap;padding:22px 48px 18px;border-bottom:3px solid var(--marke)}'
  + '.marke-name{display:block;font-size:19px;font-weight:700;color:var(--marke);letter-spacing:-0.01em}'
  + '.marke-zusatz{display:block;font-size:12px;color:var(--tinte-blass);text-transform:uppercase;letter-spacing:0.1em;margin-top:2px}'
  + '.pfad{font-size:12.5px;color:var(--tinte-weich);text-align:right}'
  + '.titelblock{padding:36px 48px 28px;border-bottom:1px solid var(--linie)}'
  + '.kennung{display:flex;align-items:center;gap:12px;margin-bottom:12px}'
  + '.nummer{font-size:13px;font-weight:700;letter-spacing:0.06em;color:var(--papier);background:var(--marke);padding:4px 10px;border-radius:3px}'
  + '.ebene{font-size:11.5px;text-transform:uppercase;letter-spacing:0.09em;color:var(--tinte-blass)}'
  + '.titelblock h1{margin:0 0 22px;font-size:30px;line-height:1.18;font-weight:600;letter-spacing:-0.02em;color:var(--tinte)}'
  + 'dl.stand{display:grid;grid-template-columns:auto 1fr;gap:4px 16px;margin:0;font-size:13px;max-width:520px}'
  + 'dl.stand dt{color:var(--tinte-blass);text-transform:uppercase;font-size:11px;letter-spacing:0.07em;padding-top:2px}'
  + 'dl.stand dd{margin:0;color:var(--tinte-weich)}'
  + '.toc{margin:28px 48px 0;padding:18px 22px;background:var(--marke-hell);border-left:3px solid var(--akzent);border-radius:0 4px 4px 0}'
  + '.toc-titel{margin:0 0 10px;font-size:11.5px;text-transform:uppercase;letter-spacing:0.1em;color:var(--marke-tief);font-weight:700}'
  + '.toc ol{margin:0;padding-left:20px;column-width:250px;column-gap:36px;font-size:13.5px}'
  + '.toc li{margin-bottom:5px;break-inside:avoid}'
  + '.toc a{color:var(--marke);text-decoration:underline;text-decoration-color:rgba(27,79,216,.35);text-underline-offset:2px}'
  + '.toc a:hover,.toc a:focus{text-decoration-color:currentColor}'
  + '.inhalt{padding:8px 48px 0}'
