  + '@media (max-width:640px){.kopf,.titelblock,.inhalt{padding-left:22px;padding-right:22px}.toc,.fuss{margin-left:22px;margin-right:22px}.titelblock h1{font-size:24px}}';

// --- Durchgang 1: Zielpfade, damit die Linkkarte vollstaendig ist ---
const eingang = $input.all().map(i => i.json).filter(s => s && s.page_id);
const karte = {};
const vorbereitet = [];

for (const s of eingang) {
  const bOrdner = sicherName(s.bereich_ordner);
  const gOrdner = sicherName(s.gruppe_nr + ' ' + (s.gruppe_titel || ''));
  const ordner = [bOrdner, gOrdner];
  const datei = s.ebene === 'gruppe'
    ? sicherName('00 Uebersicht ' + s.gruppe_nr + ' ' + s.klartext) + '.html'
    : sicherName(s.prozess_nr + ' ' + s.klartext) + '.html';

  karte[String(s.page_id)] = { ordner, datei };
  vorbereitet.push({ s, ordner, datei });
}

// --- Durchgang 2: Dokument bauen ---
const jetzt = $now;
const aus = [];

for (const v of vorbereitet) {
  const s = v.s;
  let h = bereinige(s.inhalt);
  h = linksUmschreiben(h, karte, v.ordner);
  const eintraege = verzeichnis(h);
  h = ankerSetzen(h, eintraege);

  const bName = s.bereich_klartext || s.bereich;
  const nummer = s.ebene === 'gruppe' ? s.gruppe_nr : s.prozess_nr;
  const ebeneLabel = s.ebene === 'gruppe' ? 'Prozessgruppe' : 'Prozess';
  const stand = s.geaendert_am ? String(s.geaendert_am).slice(0, 10) : 'unbekannt';

  const toc = eintraege.length
    ? '<nav class="toc" aria-label="Inhalt"><h2 class="toc-titel">Inhalt</h2><ol>'
      + eintraege.map(e => '<li><a href="#' + e.id + '">' + e.text + '</a></li>').join('')
      + '</ol></nav>'
    : '';

  const html = '<!DOCTYPE html>\n<html lang="de">\n<head>\n<meta charset="utf-8">\n'
    + '<meta name="viewport" content="width=device-width, initial-scale=1">\n'
    + '<title>' + esc(nummer) + ' ' + esc(s.klartext) + ' – RWG Rheinland eG</title>\n'
    + '<meta name="prozess-id" content="' + esc(nummer) + '">\n'
    + '<meta name="bereich" content="' + esc(s.bereich) + ' ' + esc(bName) + '">\n'
    + '<meta name="stand" content="' + esc(stand) + '">\n'
    + '<meta name="quelle" content="' + esc(s.web_url) + '">\n'
    + '<style>' + STIL + '</style>\n</head>\n<body>\n<div class="blatt">\n'
    + '<header class="kopf"><div class="marke"><span class="marke-name">RWG Rheinland eG</span>'
    + '<span class="marke-zusatz">Prozessdokumentation</span></div>'
    + '<div class="pfad">' + esc(s.bereich) + ' ' + esc(bName) + ' &rsaquo; ' + esc(s.gruppe_nr) + '</div></header>\n'
    + '<div class="titelblock"><div class="kennung"><span class="nummer">' + esc(nummer) + '</span>'
    + '<span class="ebene">' + ebeneLabel + '</span></div>'
    + '<h1>' + esc(s.klartext) + '</h1>'
    + '<dl class="stand"><dt>Stand</dt><dd>' + esc(stand) + '</dd>'
    + '<dt>Bereich</dt><dd>' + esc(bName) + '</dd>'
    + '<dt>Gültig für</dt><dd>RWG Rheinland eG</dd></dl></div>\n'
    + toc + '\n<main class="inhalt">\n' + h + '\n</main>\n'
    + '<footer class="fuss"><p class="fuss-haupt">Diese Seite wird aus dem RWG ProzessHub erzeugt und bei '
    + 'Änderungen automatisch ersetzt. Änderungen bitte im ProzessHub vornehmen, nicht in dieser Datei. '
    + '<strong>Änderungen am ProzessHub erfolgen ausschliesslich durch Sebastian Linges nach Rücksprache.</strong></p>'
    + '<p class="fuss-meta">Stand ' + esc(stand) + ' · Quelle ' + esc(nummer)
    + ' im ProzessHub · Erzeugt ' + jetzt.toFormat('dd.LL.yyyy') + '</p></footer>\n'
    + '</div>\n</body>\n</html>';

  const buf = Buffer.concat([
    Buffer.from([0xEF, 0xBB, 0xBF]),
    Buffer.from(html, 'utf8')
  ]);

  aus.push({
    json: Object.assign({}, s, {
      html,
      sp_ordner: v.ordner.join('/'),
      sp_ordner_blatt: v.ordner[v.ordner.length - 1],
      sp_datei: v.datei,
      sp_pfad: v.ordner.join('/') + '/' + v.datei,
      sp_pfad_url: v.ordner.map(encodeURIComponent).join('/') + '/' + encodeURIComponent(v.datei),
      abschnitte: eintraege.length,
      html_bytes: buf.length,
      status: 'aufbereitet'
    }),
    binary: {
      datei: {
        data: buf.toString('base64'),
        mimeType: 'text/html',
        fileName: v.datei,
        fileExtension: 'html'
      }
    }
  });
}

return aus;

// ============================================================
// Was der Lauf getan hat, in Zahlen. Solange sharepointAktiv
// false ist, wird nichts abgelegt und nichts entfernt - das
// steht dann auch so im Ergebnis.
// ============================================================
const cfg = $('Config').first().json;

const normalisiert = $('Seiten normalisieren').all().map(i => i.json);
const abgeglichen = $('Abgleich').all().map(i => i.json);

let aufbereitet = [];
try {
  aufbereitet = $('Dokument bauen').all().map(i => i.json).filter(x => x && x.sp_pfad);
} catch (e) {
  aufbereitet = [];
}

const zuSpiegeln = abgeglichen.filter(x => x.aktion === 'spiegeln');
const zuEntfernen = abgeglichen.filter(x => x.aktion === 'entfernen');
const unveraendert = abgeglichen.filter(x => x.aktion === 'nichts');

const neu = zuSpiegeln.filter(x => x.grund === 'neu').length;
const geaendert = zuSpiegeln.filter(x => x.grund === 'geaendert').length;

// Umgezogene entstehen, wenn sich eine Ueberschrift geaendert hat und die
// Datei dadurch an einen anderen Ort gehoert. Ohne eigenen Zaehler faende
// sich eine Umbenennung in keiner Zahl wieder - abgelegt wurde etwas,
// aber weder neu noch geaendert.
const umgezogen = zuSpiegeln.filter(x => x.grund === 'umgezogen').length;

const ohneGruppentitel = normalisiert.filter(x => x.gruppe_titel_fehlt).map(x => x.gruppe_nr);
const ohneInhalt = normalisiert.filter(x => x.inhalt_leer).map(x => x.titel);
const ohneStand = normalisiert.filter(x => !x.geaendert_am).length;
const erste = normalisiert.length ? normalisiert[0] : {};

const spAktiv = cfg.sharepointAktiv === true;
const bereiche = Array.from(new Set(normalisiert.map(x => x.bereich))).sort();

return [{
  json: {
    bereich_gefiltert: cfg.bereichFilter || '(alle)',
    bereiche_verarbeitet: bereiche,
    seiten_erkannt: normalisiert.length,
    davon_gruppen: normalisiert.filter(x => x.ebene === 'gruppe').length,
    davon_prozesse: normalisiert.filter(x => x.ebene === 'prozess').length,
    neu: neu,
    geaendert: geaendert,
    umgezogen: umgezogen,
    unveraendert: unveraendert.length,
    zu_entfernen: zuEntfernen.length,
    dokumente_aufbereitet: aufbereitet.length,
    tatsaechlich_abgelegt: spAktiv ? aufbereitet.length : 0,
    hinweis: spAktiv
      ? 'SharePoint aktiv.'
      : 'sharepointAktiv steht auf false und die SharePoint-Nodes sind deaktiviert. Es wurde nichts abgelegt und nichts entfernt.',
    uebersprungen_bereiche_ohne_ordner: erste.bereiche_ohne_ordner || [],
    uebersprungen_seiten: erste.seiten_ohne_ordner || 0,
    ordner_ohne_kuerzel_im_namen: erste.ordner_ohne_kuerzel || [],
    bereichsordner_dubletten: erste.ordner_doppelt || [],
    gruppen_ohne_titel: Array.from(new Set(ohneGruppentitel)),
    seiten_ohne_inhalt: ohneInhalt.slice(0, 10),
    seiten_ohne_stand: ohneStand,
    html_bytes_gesamt: aufbereitet.reduce((s, x) => s + (x.html_bytes || 0), 0),
    beispiel_ordner: aufbereitet.length ? aufbereitet[0].bereich_ordner : '',
    beispiel_pfad: aufbereitet.length ? aufbereitet[0].sp_pfad : '',
    fertig_um: $now.toISO()
  }
}];

// ============================================================
// ZIELPFADE
//
// Der Ablageort einer Seite entsteht aus den Ueberschriften:
//   <Bereichsordner>/<Gruppennummer Gruppentitel>/<Prozessnummer Klartext>.html
//
// Er wird hier berechnet und nicht erst in "Dokument bauen" - dort
// kaeme er zu spaet. "Abgleich" entscheidet vorher, was zu tun ist,
// und koennte einen Umzug gar nicht bemerken. Genau daran sind
// Umbenennungen bisher unbemerkt vorbeigelaufen.
//
// sicherName ist zeichengleich mit der Fassung in "Dokument bauen".
// Weichen die beiden auseinander, raeumt "Ueberzaehlige bestimmen"
// am Ende Dateien weg, die derselbe Lauf gerade geschrieben hat.
// ============================================================
function sicherName(s) {
  return String(s || '')
    .replace(/&amp;/g, 'und').replace(/&/g, 'und')
    .replace(/[":*<>?/\\|]/g, '-')
    .replace(/[–—]/g, '-')
    .replace(/\s+/g, ' ')
    .replace(/^[.\s]+|[.\s]+$/g, '')
    .slice(0, 120);
}

return $input.all().map(item => {
  const s = item.json || {};
  if (!s.page_id) return { json: s };

  const bOrdner = sicherName(s.bereich_ordner);
  const gOrdner = sicherName(s.gruppe_nr + ' ' + (s.gruppe_titel || ''));
  const ordner = [bOrdner, gOrdner];
  const datei = s.ebene === 'gruppe'
    ? sicherName('00 Uebersicht ' + s.gruppe_nr + ' ' + s.klartext) + '.html'
    : sicherName(s.prozess_nr + ' ' + s.klartext) + '.html';

  return { json: Object.assign({}, s, {
    sp_ordner: ordner.join('/'),
    sp_datei: datei,
    sp_pfad: ordner.join('/') + '/' + datei,
    sp_pfad_url: ordner.map(encodeURIComponent).join('/') + '/' + encodeURIComponent(datei),
    bereich_ordner_sicher: bOrdner
  }) };
});

// ============================================================
// WAS LIEGT DA, DAS NICHT DAHIN GEHOERT
//
// Der Flow arbeitete bisher aus dem Gedaechtnis: Die Data Table sagte
// ihm, was er zuletzt abgelegt hat. Was wirklich in SharePoint liegt,
// hat er nie nachgesehen - deshalb blieben Dateien aus Umbenennungen
// unbemerkt liegen.
//
// Hier wird der Ist-Zustand gegen die Soll-Liste gehalten. Was nicht
// auf der Liste steht, wird entfernt - unabhaengig davon, warum es da
// liegt: Umbenennung, abgebrochener Lauf, von Hand hineinkopiert.
//
// DREI SICHERUNGEN, jede einzeln notwendig:
//   1. Nur innerhalb der eigenen Bereichsordner und nur .html. Die
//      Bibliothek gehoert dem Flow nicht allein.
//   2. Leere Soll-Liste heisst Abbruch. Liefert Confluence nichts,
//      duerfte sonst der gesamte Spiegel geloescht werden.
//   3. Dieselbe Anteilsschwelle wie beim Abgleich.
//
// Der Knoten haengt hinter "Zusammenfassung", die zwei Eingaenge hat
// und deshalb zweimal anlaufen kann. Der zweite Durchlauf liefert
// nichts, sonst wuerde doppelt geloescht.
// ============================================================
if ($runIndex > 0) return [];

const cfg = $('Config').first().json;
const maxProzent = Number(cfg.loeschSicherungProzent != null ? cfg.loeschSicherungProzent : 35);
const gruppenSpiegeln = cfg.gruppenseitenSpiegeln === true;

const seiten = $('Zielpfade bestimmen').all().map(i => i.json).filter(s => s && s.page_id);

const soll = new Set();
const bereiche = new Set();

for (const s of seiten) {
  const wurzel = String(s.bereich_ordner_sicher || '');
  if (wurzel) bereiche.add(wurzel);

  // Gruppenseiten liefern nur den Ordnernamen, solange der Schalter aus
  // steht. Sie gehoeren dann nicht auf die Soll-Liste - ihr Bereich aber
  // sehr wohl aufs eigene Gebiet.
  if (s.ebene === 'gruppe' && !gruppenSpiegeln) continue;

  const pfad = String(s.sp_pfad || '');
  if (pfad) soll.add(pfad);
}

if (soll.size === 0) {
  throw new Error('AUFRAEUMEN_ABGEBROCHEN: Die Soll-Liste ist leer. Es wird nichts entfernt.');
}

// --- Ist-Zustand einsammeln und entdoppeln -------------------
// Der Delta-Abruf liefert einen Eintrag mehrfach, wenn er sich mehrmals
// geaendert hat.
const istNachId = {};
for (const item of $('Ablage lesen').all()) {
  const b = item.json || {};
  for (const v of (b.value || [])) {
    if (v && v.id) istNachId[String(v.id)] = v;
  }
}

function pfadVon(v) {
  const roh = (v.parentReference && v.parentReference.path) || '';
  const rein = roh.replace(/^\/drives?(\/[^/]+)?\/root:?/, '');
  const eltern = rein ? decodeURIComponent(rein).replace(/^\//, '') : '';
  return eltern ? eltern + '/' + v.name : String(v.name || '');
}

const ueberzaehlig = [];
for (const id of Object.keys(istNachId)) {
  const v = istNachId[id];
  if (v.deleted) continue;
  if (!v.file) continue;
  const pfad = pfadVon(v);
  if (!/\.html$/i.test(pfad)) continue;
  if (!bereiche.has(pfad.split('/')[0])) continue;
  if (soll.has(pfad)) continue;
  ueberzaehlig.push({
    sp_pfad: pfad,
    item_id: v.id,
    grund: 'liegt nicht auf der Soll-Liste'
  });
}

const grenze = Math.max(5, soll.size * (maxProzent / 100));
if (ueberzaehlig.length > grenze) {
  throw new Error(
    'AUFRAEUMEN_ABGEBROCHEN: ' + ueberzaehlig.length + ' von ' + soll.size +
    ' Dateien gaelten als ueberzaehlig, erlaubt sind ' + maxProzent + ' Prozent. Es wird nichts entfernt.'
  );
}

return ueberzaehlig.map(u => ({ json: u }));
